// Conformance test for the FTL parser.
//
// Every case below is a source snippet together with the canonical summary of
// the abstract syntax tree that the reference implementation produces for it:
// `@fluent/syntax` 0.19, whose fixture set (`fixtures_reference`) is the
// normative syntax test suite for Project Fluent 1.0. The expectations were
// generated by running that implementation over the snippets, and `fluent-syntax`
// (Rust) as well as `python-fluent` agree with them wherever the three
// implementations agree with each other. Any divergence in entries, patterns,
// expressions, attributes, variant keys or junk boundaries fails a case here.
//
// The list is generated by /tmp/gen_dart_test.py; the same data is available in
// `test/data/ftl_reference_corpus.json` for other tools.
//
// Rules that the three implementations disagree on, and the choice made here:
//
//   * `python-fluent` keeps two Syntax 0.4 compatibility rules — a junk ends at
//     a line that starts with `//` or `[[`, and `[[` does not start a variant —
//     while the EBNF, `@fluent/syntax` and `fluent-syntax` only stop a junk at
//     a line that starts with a letter, `-` or `#`. The EBNF is followed here.
//   * `python-fluent` never re-scans the line an error was reported on, while
//     `@fluent/syntax` rewinds to the line end before the error first; the
//     latter behaviour is followed here (see `junk/error-on-second-line`).
//   * an out-of-range Unicode escape (`"\U110000"`) makes `@fluent/syntax`
//     throw an unhandled `RangeError`; it is a plain junk entry here.
//
// Three more intentional deviations are covered by hand-written tests instead
// of the generated list below: CR/CRLF line ends are normalized while parsing,
// string escapes are decoded while parsing (the reference decodes them when a
// value is written), and the corpus stores summaries instead of fixture trees.

import 'package:rustok_i18n/rustok_i18n.dart';
import 'package:test/test.dart';

/// Canonical text form of a parsed resource, matching the reference fixtures.
String summarize(FtlResource resource) => resource.entries.map(_entry).join(' || ');

String _entry(FtlEntry entry) {
  if (entry is FtlMessage) {
    return 'Message(${entry.id}) comment=${_comment(entry.comment)} '
        'value=${_pattern(entry.value)} attrs=${_attributes(entry.attributes)}';
  }
  if (entry is FtlTerm) {
    return 'Term(${entry.id}) comment=${_comment(entry.comment)} '
        'value=${_pattern(entry.value)} attrs=${_attributes(entry.attributes)}';
  }
  if (entry is FtlComment) {
    return 'Comment(level=${entry.level}, ${_q(entry.content)})';
  }
  if (entry is FtlJunk) {
    return 'Junk(${_q(entry.content)})';
  }
  return entry.runtimeType.toString();
}

String _comment(String? comment) => comment == null ? 'null' : _q(comment);

/// Quotes [value] the way `JSON.stringify` does, which is how the expected
/// summaries are written: quotes, backslashes, the four named control escapes,
/// any other control character and *lone* surrogates become escapes, while a
/// surrogate pair stays the single character it stands for.
String _q(String value) {
  final buffer = StringBuffer('"');
  final units = value.codeUnits;
  for (var i = 0; i < units.length; i++) {
    final unit = units[i];
    if (unit == 0x22) {
      buffer.write(r'\"');
    } else if (unit == 0x5C) {
      buffer.write(r'\\');
    } else if (unit == 0x08) {
      buffer.write(r'\b');
    } else if (unit == 0x09) {
      buffer.write(r'\t');
    } else if (unit == 0x0A) {
      buffer.write(r'\n');
    } else if (unit == 0x0C) {
      buffer.write(r'\f');
    } else if (unit == 0x0D) {
      buffer.write(r'\r');
    } else if (unit < 0x20) {
      buffer.write('\\u${unit.toRadixString(16).padLeft(4, '0')}');
    } else if (unit >= 0xD800 && unit <= 0xDFFF) {
      if (_isHighSurrogate(units, i)) {
        // A valid pair is one character: copy it and skip the low surrogate.
        buffer.writeCharCode(
          0x10000 + ((unit - 0xD800) << 10) + (units[i + 1] - 0xDC00),
        );
        i++;
      } else {
        buffer.write('\\u${unit.toRadixString(16).padLeft(4, '0')}');
      }
    } else {
      buffer.writeCharCode(unit);
    }
  }
  buffer.write('"');
  return buffer.toString();
}

bool _isHighSurrogate(List<int> units, int index) =>
    units[index] >= 0xD800 &&
    units[index] <= 0xDBFF &&
    index + 1 < units.length &&
    units[index + 1] >= 0xDC00 &&
    units[index + 1] <= 0xDFFF;

String _attributes(List<FtlAttribute> attributes) =>
    '[${attributes.map((a) => '${a.id}:${_pattern(a.value)}').join(', ')}]';

String _pattern(FtlPattern? pattern) {
  if (pattern == null) return 'null';
  final elements = pattern.elements.map((element) {
    if (element is FtlTextElement) return 'Text(${_q(element.value)})';
    return 'Placeable(${_expression((element as FtlPlaceable).expression)})';
  });
  return '[${elements.join(', ')}]';
}

/// Arguments of a call: omitted when there are none, as in the reference.
String _callArgs(List<FtlExpression> positional, Map<String, FtlExpression> named) {
  if (positional.isEmpty && named.isEmpty) return '';
  final pos = positional.map(_expression).join(', ');
  final nam = named.entries.map((e) => '${e.key}=${_expression(e.value)}').join(', ');
  return ', pos=[$pos], named=[$nam]';
}

String _expression(FtlExpression expression) {
  if (expression is FtlStringLiteral) return 'Str(${_q(expression.value)})';
  if (expression is FtlNumberLiteral) return 'Num(${expression.value})';
  if (expression is FtlVariableReference) return 'Var(${expression.id})';
  if (expression is FtlMessageReference) {
    final attribute = expression.attribute == null ? '' : '.${expression.attribute}';
    return 'Msg(${expression.id}$attribute)';
  }
  if (expression is FtlTermReference) {
    final attribute = expression.attribute == null ? '' : '.${expression.attribute}';
    final named = expression.arguments ?? const <String, FtlExpression>{};
    return 'Term(${expression.id}$attribute'
        '${_callArgs(expression.positionalArguments, named)})';
  }
  if (expression is FtlFunctionReference) {
    return 'Func(${expression.name}${_callArgs(expression.positional, expression.named)})';
  }
  if (expression is FtlPlaceableExpression) {
    return 'Placeable(${_expression(expression.expression)})';
  }
  if (expression is FtlSelectExpression) {
    final variants = expression.variants.map((v) {
      final marker = v.isDefault ? '*' : '';
      return '$marker[${v.key}]:${_pattern(v.value)}';
    });
    return 'Select(${_expression(expression.selector)} -> [${variants.join(', ')}])';
  }
  return expression.runtimeType.toString();
}

class _Case {
  const _Case(this.label, this.source, this.expected);

  final String label;
  final String source;
  final String expected;
}

void main() {
  group('FTL parser conformance', () {
    test('the corpus covers the reference fixture set', () {
      final fixtures = _cases.where((c) => c.label.startsWith('fixture '));
      expect(fixtures.length, greaterThanOrEqualTo(30));
      expect(_cases.length, greaterThanOrEqualTo(250));
    });

    for (final testCase in _cases) {
      test(testCase.label, () {
        expect(summarize(FtlParser.parse(testCase.source)), testCase.expected);
      });
    }
  });

  group('documented deviations from the reference', () {
    test('CR and CRLF line ends are normalized while parsing', () {
      final resource = FtlParser.parse('key = one\r\n  continued\rnext = two\r\n');
      expect(summarize(resource),
          'Message(key) comment=null value=[Text("one\\ncontinued")] attrs=[] || '
          'Message(next) comment=null value=[Text("two")] attrs=[]');
    });

    test('string escapes are decoded while parsing', () {
      final resource = FtlParser.parse('key = {"\\u0041\\U01F602"}\n');
      expect(summarize(resource),
          'Message(key) comment=null value=[Placeable(Str("A\u{1F602}"))] attrs=[]');
    });

    test('a lone surrogate escape survives as one code unit', () {
      final resource = FtlParser.parse('key = {"\\ud83d"}\n');
      expect(summarize(resource),
          'Message(key) comment=null value=[Placeable(Str("\\ud83d"))] attrs=[]');
    });

    test('an out-of-range escape is junk instead of a crash', () {
      final resource = FtlParser.parse('key = {"\\U110000"}\n');
      expect(resource.entries.whereType<FtlJunk>(), hasLength(1));
      expect(resource.messages, isEmpty);
    });
  });
}

